select 'دالّة' as "النوع", name as "الناقص" from expected_fn e
 where not exists (select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
                    where n.nspname='public' and p.proname = e.name)
union all
select 'جدول', name from expected_tb e
 where not exists (select 1 from pg_tables t where t.schemaname='public' and t.tablename = e.name)
union all
select 'منظور', name from expected_vw e
 where not exists (select 1 from pg_views v where v.schemaname='public' and v.viewname = e.name)
union all
select 'مفتاح ربط', name from expected_fk e
 where not exists (select 1 from pg_constraint c join pg_class t on t.oid=c.conrelid
                     join pg_namespace n on n.oid=t.relnamespace
                    where c.contype='f' and n.nspname='public' and c.conname = e.name)
order by 1, 2;
